// One item per task: ALL its candidates (cleaned, with a normalised URL for de-duplication; nothing is cut) and
// statistics for search_runs, including the fixed academic databases' hits.
const norm = (u) => u.replace(/#.*$/, '').replace(/[?&]utm_[^&]+/g, '').replace(/\/$/, '').toLowerCase();
return $input.all().map((it, i) => {
  const task = $('Task + Search Skill').itemMatching(i).json;
  const j = it.json, codex = task.engine !== 'api';
  let list = [], stats = {}, error = '', runId = '', queries = [];
  if (codex) {
    list = j.candidates || []; stats = j.stats || {}; runId = j.run_id || ''; queries = j.queries_tried || [];
    error = j.ok ? '' : (j.error?.message || j.error || 'codex runner failed');
  } else {
    const text = j.output?.flatMap(o => o.content || []).find(c => c.type === 'output_text')?.text ?? j.text ?? '';
    try { list = (typeof text === 'object' ? text : JSON.parse(text)).candidates || []; } catch (e) { error = j.error?.message || 'no parsable answer'; }
    stats = { input_tokens: j.usage?.input_tokens || 0, output_tokens: j.usage?.output_tokens || 0,
              web_searches: (j.output || []).filter(o => o.type === 'web_search_call').length };
  }
  const candidates = list.filter(c => /^https?:\/\//.test(c.url || ''))
    .map(c => ({ ...c, why_relevant: c.why_relevant + (c.checked ? ` [Checked: ${c.checked}]` : ''), url_norm: norm(c.url),
                 search_engine: codex ? 'codex' : 'api', domain: task.domain || '', database: c.database || 'web',
                 doi: String(c.doi || '').replace(/^https?:\/\/(dx\.)?doi\.org\//i, '').trim(),
                 found_via_url: /^https?:\/\//.test(c.found_via || '') ? c.found_via : '', relation: c.found_via ? (c.relation || '') : '',
                 files: (Array.isArray(c.files) ? c.files : []).filter(f => /^https?:\/\//.test(f?.url || '')) }));
  return { json: { candidates, run: { pipeline_run: task.run_id || null, academic: codex ? (j.academic_log || []) : [],
    engine: codex ? 'codex' : 'api', domain: task.domain || '', country: task.country, language: task.language, source_type: task.source_type,
    candidates: candidates.length, duration_s: stats.duration_s ?? null, commands: stats.commands ?? null, web_searches: stats.web_searches ?? null,
    input_tokens: stats.input_tokens ?? null, cached_input_tokens: stats.cached_input_tokens ?? null, output_tokens: stats.output_tokens ?? null,
    codex_run: runId, queries, error: String(error).slice(0, 500) } } };
});
